INSERT /*
--------------------------------------------------------------------------
-- 업무파트명                : 프레임워크
-- 프로그램 한글명 또는 화면명 : 어플리케이션시스템알림등록
-- 프로그램명                : AppliSystNtfyPati
-------------------------------------------------------------------------- */
INTO S_TFG.GL_APPLI_SYST_NTFY_PATI
(   APPLI_SYST_NTFY_PATI_ID
,APPLI_SYST_NTFY_KD_CD
,APPLI_DUTJ_CD
,APPLI_DUTJ_PRJC_CD
,NTFY_MSG_CT
,NTFY_OCC_DT
,NTFY_CFM_DT
,NTFY_TRGT_PRAF_NO
,SHMS_PML_YN
,NTFY_CFM_YN
,SYST_RGI_DT
,SYST_RGI_PRAF_NO
,SYST_RGI_OGNZ_NO
,SYST_RGI_SYST_CD
,SYST_RGI_PRGR_ID
